  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "terms-B", "20");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  await ui.setToday(pg_uma, "2026-03-19");
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "0.40"}));
  expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.reassign(pg_wes, c_ben_0, "Cam")).toBe(true);
  expect(await ui.hold(pg_wes, p_ben, {})).toBe(true);
  expect(await ui.periodAction(pg_wes, "P1", "close")).toBe(true);
  await ui.refresh(pg_wes);
  expect(await ui.setRate(pg_wes, {"grade": "B", "pct": "20.00"})).toBe(true);
  const c_ada_0 = ui.must(await ui.addClaim(pg_wes, p_ada, {"amount": "99.95"}));
  expect(await ui.addPatron(pg_wes, p_ada, "Cam")).toBe(true);
  expect(await ui.addPatron(pg_wes, p_ada, "Ben")).toBe(true);
  expect(await ui.setRate(pg_wes, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.editPerson(pg_wes, p_ada, {"grade": "A", "gradeFrom": "2026-03-05"})).toBe(true);
  expect(await ui.claimAction(pg_wes, c_ben_0, "void")).toBe(true);
  await ui.refresh(pg_wes);
  const c_ben_0_2 = ui.must(await ui.addClaim(pg_wes, p_ben, {"amount": "25.00", "date": "2026-03-28"}));
  const c_ada_1 = ui.must(await ui.addClaim(pg_wes, p_ada, {"amount": "3.33", "date": "2026-03-28"}));
  expect(await ui.editPerson(pg_wes, p_ada, {"grade": "C"})).toBe(true);
  expect(await ui.addPatron(pg_wes, p_ada, "Cam")).toBe(false);
  expect(await ui.addClaim(pg_wes, p_ada, {"amount": "20.00", "date": "2026-03-15"})).toBeNull();
  await ui.refresh(pg_wes);
  expect(await ui.reassign(pg_wes, c_ada_1, "Ben")).toBe(true);
  expect(await ui.bulkOpen(pg_wes, [c_ada_0, c_ada_1])).toEqual({ opened: 2, refused: 0 });
  await ui.refresh(pg_wes);
  await ui.setToday(pg_wes, "2026-04-12");
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.00");
