  await expect(pg_wes.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0_2).getByTestId("claim-due")).toHaveText("5.00");
  await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-overdue-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-date")).toHaveText("2026-03-19");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due-by")).toHaveText("2026-03-29");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-overdue")).toHaveText("no");
  await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-overdue-total")).toHaveText("19.99");
  await expect(pg_wes.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-date")).toHaveText("2026-03-19");
  await expect(pg_wes.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("19.99");
  await expect(pg_wes.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due-by")).toHaveText("2026-03-29");
  await expect(pg_wes.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-overdue")).toHaveText("yes");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-overdue-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-date")).toHaveText("2026-03-28");
  await expect(pg_wes.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due-by")).toHaveText("2026-04-07");
  await expect(pg_wes.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-overdue")).toHaveText("yes");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0_2).getByTestId("claim-date")).toHaveText("2026-03-28");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0_2).getByTestId("claim-due")).toHaveText("5.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0_2).getByTestId("claim-due-by")).toHaveText("2026-04-07");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0_2).getByTestId("claim-overdue")).toHaveText("no");
  await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("19.99");

